    });
  });

  describe("date of birth (ADR-0015)", () => {
    it("stores and returns the date of birth", async () => {
      const { identity } = setup();
      const person = await identity.registerPerson({ ...erika, dateOfBirth: "1990-06-15" });
      expect(person.dateOfBirth).toBe("1990-06-15");
      expect((await identity.getPerson(person.id))?.dateOfBirth).toBe("1990-06-15");
    });

    it("returns null when the date of birth was not given", async () => {
      const { identity } = setup();
      const person = await identity.registerPerson(erika);
      expect(person.dateOfBirth).toBeNull();
      expect((await identity.getPerson(person.id))?.dateOfBirth).toBeNull();
    });

    it("accepts today's business date", async () => {
      const { identity } = setup("2027-01-05T08:00:00Z");
      const person = await identity.registerPerson({ ...erika, dateOfBirth: "2027-01-05" });
      expect(person.dateOfBirth).toBe("2027-01-05");
    });

    it("rejects a date of birth in the future", async () => {
      const { identity } = setup("2027-01-05T08:00:00Z");
      await expect(
        identity.registerPerson({ ...erika, dateOfBirth: "2027-01-06" }),
      ).rejects.toBeInstanceOf(DateOfBirthInFutureError);
    });

    it("judges the future by the Europe/Berlin date", async () => {
      // 23:30 UTC on 5 January is already 6 January in Berlin.
      const { identity } = setup("2027-01-05T23:30:00Z");
      const person = await identity.registerPerson({ ...erika, dateOfBirth: "2027-01-06" });
      expect(person.dateOfBirth).toBe("2027-01-06");
    });

    it.each(["1990-6-15", "15.06.1990", "1990-06-15T00:00:00Z", "1990-02-30", "1990-13-01"])(
      "rejects %s as a date of birth",
      async (dateOfBirth) => {
        const { identity } = setup();
        await expect(identity.registerPerson({ ...erika, dateOfBirth })).rejects.toBeInstanceOf(
          InvalidDateOfBirthError,
        );
      },
    );

    it("does not store a person with a rejected date of birth", async () => {
      const { bus, identity } = setup();
      await identity.registerPerson({ ...erika, dateOfBirth: "2100-01-01" }).catch(() => {});
      expect(bus.published).toHaveLength(0);
      await expect(identity.registerPerson(erika)).resolves.toMatchObject({ dateOfBirth: null });
    });
  });
});

